from __future__ import absolute_import
import time
from functools import partial
from selenium.webdriver.common.by import By
from .panels.navigation import NavigationPanel
from .panels.view import ViewPanel
from .panels.details import DetailPanel
from .common_page import CommonPage


class Alarms(CommonPage):
    """
    The class corresponding to Alarms page on selenium_coam web, all operations under Alarms page will be implemented or
    added in its corresponding classes.
    """
    _instance_dict = {}

    def __init__(self):
        if not self._instance_dict:
            self._instance_dict = {"Active Alarms": ActiveAlarmsPage(),
                                   "Alarm History": AlarmHistoryPage(),
                                   "Fault Toggling History": FaultTogglingHistory()}
        super(Alarms, self).__init__(self._instance_dict)


class AlarmsCommonAction(NavigationPanel, ViewPanel, DetailPanel):
    _ALARM_COLUMN_HEADER_XPATH = "//th[@ng-repeat='header in fmHeaders']//*[text()]"
    _ALARMS_ROW_XPATH = "//tr[@ng-repeat='alarm in $ctrl.alarms']"
    _ALARMS_SEVERITY_XPATH = "/td[1]//*[name()='path']"

    def _input_filter_context(self, alarm_filter, timeout, alarm_filter_xpath):
        locator = (By.XPATH, alarm_filter_xpath)
        if alarm_filter:
            self.insert_text_to_enable_element(locator, alarm_filter, timeout)
        else:
            self.clear_text_of_enable_element(locator, timeout)

    def _get_alarms_info(self, timeout):
        alarm_list = []
        key_list = self.get_fields_info_from_row(self._ALARM_COLUMN_HEADER_XPATH, timeout)
        alarm_number = len(self.driver.find_elements_by_xpath(self._ALARMS_ROW_XPATH))
        for index in range(1, alarm_number + 1):
            alarms_severity_xpath = self._ALARMS_ROW_XPATH + "[{}]".format(index) + self._ALARMS_SEVERITY_XPATH
            severity = self.get_attribute_by_xpath(alarms_severity_xpath, 'class', timeout)
            alarm_info_xpath = self._ALARMS_ROW_XPATH + "[{}]//*[text()]".format(index)
            value_list = self.get_fields_info_from_row(alarm_info_xpath, timeout)
            value_list.insert(0, severity)
            alarm_list.append(dict(zip(key_list, value_list)))
        return alarm_list

    def get_alarms_info(self, alarm_filter, timeout, alarm_filter_xpath):
        self._input_filter_context(alarm_filter, timeout, alarm_filter_xpath)
        return self._get_alarms_info(timeout)

    def save_alarms(self, save_button_xpath, download_timeout=30):
        start_time = time.time()
        self.click_enabled_element_after_visible((By.XPATH, save_button_xpath))
        return self.download_files(start_time, download_timeout)


class ActiveAlarmsPage(object):
    MENU_ROUTE_LIST = ['Alarms', 'Alarm Management', 'Active Alarms']

    def __init__(self):
        self._view_panel = ActiveAlarmsPageViewPanel()
        self.common_actions = {
            "get_active_alarm_info": self._view_panel.get_active_alarm_info,
            "save_current_alarms": self._view_panel.save_current_alarms,
        }
        self.__dict__.update(self.common_actions)


class ActiveAlarmsPageViewPanel(ViewPanel):
    _ACTIVE_ALARM_FILTER_XPATH = "//div[@ng-if='isTabActive(tabs.currentAlarms)']//input"
    _SAVE_CURRENT_ALARMS_XPATH = "//div[@alarms-type='current']//button"

    def __init__(self):
        self.common_actions = {
            "get_active_alarm_info": partial(AlarmsCommonAction().get_alarms_info,
                                             alarm_filter_xpath=self._ACTIVE_ALARM_FILTER_XPATH),
            "save_current_alarms": partial(AlarmsCommonAction().save_alarms, self._SAVE_CURRENT_ALARMS_XPATH)
        }
        self.__dict__.update(self.common_actions)


